<?php
/**
 * Select Animation: the GSAP animations of the layout blocks. A block picks one or more presets (fade in,
 * slide out up, and so on) and modifiers (duration, delay, stagger, ease, scroll start and end, scrub, pin,
 * hide on a device). The choice is written as data-animate, and the GSAP runtime in assets/js plays it.
 *
 * The presets are the team's own list from the snn child theme (animation-presets.php, generated by
 * gen-animation-presets.js). A value that is not in the list is dropped, so a block can only play what the
 * list has.
 *
 * The animations are on only when the GSAP setting is on (Interactions and Animations settings, features/
 * interactions.php). That setting loads the GSAP runtime on every front-end page, so the blocks do not load it
 * again. In the editor the canvas does not play the animations; the panel shows their names.
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

class SNN_Animation {

	/** The most animations one block may carry. */
	const MAX = 20;

	/** The list, once read: array of [ group, value, label ]. */
	private static $rows = null;

	/** The list, as the panel shows it: groups in order, each with its items. */
	public static function options() {
		$groups = array();
		foreach ( self::rows() as $row ) {
			list( $group, $value, $label ) = $row;
			if ( ! isset( $groups[ $group ] ) ) {
				$groups[ $group ] = array( 'label' => $group, 'items' => array() );
			}
			$groups[ $group ]['items'][] = array(
				'value' => $value,
				'label' => $label,
			);
		}
		return array_values( $groups );
	}

	/** Every value the list allows. */
	public static function allowed() {
		return array_column( self::rows(), 1 );
	}

	/** Keeps the values in the list, in the order given, without repeats. Anything else is dropped. */
	public static function clean_tokens( $value ) {
		if ( ! is_array( $value ) ) {
			return array();
		}
		$allowed = self::allowed();
		$out     = array();
		foreach ( $value as $token ) {
			if ( ! is_string( $token ) || ! in_array( $token, $allowed, true ) || in_array( $token, $out, true ) ) {
				continue;
			}
			$out[] = $token;
			if ( count( $out ) >= self::MAX ) {
				break;
			}
		}
		return $out;
	}

	/** The data-animate value for a block: its tokens, separated by commas, as the runtime reads them. */
	public static function data_animate( array $tokens ) {
		return implode( ',', self::clean_tokens( $tokens ) );
	}

	/**
	 * True when the GSAP setting is on. The panel shows the Animations icon only then, and a block writes its
	 * data-animate only then. Without the features file (its feature is off), it is always false.
	 */
	public static function enabled() {
		if ( ! function_exists( 'snn_get_interactions_settings' ) ) {
			return false;
		}
		$settings = snn_get_interactions_settings();
		return is_array( $settings ) && ! empty( $settings['enqueue_gsap'] );
	}

	/** The rows of the generated list, read once. */
	private static function rows() {
		if ( null === self::$rows ) {
			$rows       = include __DIR__ . '/animation-presets.php';
			self::$rows = is_array( $rows ) ? $rows : array();
		}
		return self::$rows;
	}
}
